"""Regenerate the S1/S2 handoff from committed manifests, not manually copied numbers."""
import json
from pathlib import Path

from nbv.visualization.demo import check_bundle
from nbv.visualization.figure_data import RegistryFigures
from nbv.visualization.replay import digest,require_exact


def verify_delivery(validation,figures,demo,actual):
    if (not validation['complete'] or validation['mismatches'] or validation['counts']!={'A':195,'B':900}
        or figures['replay_validation']!=validation['counts'] or demo['verification']!=validation['counts']
        or demo['total_bytes']!=actual['total_bytes'] or demo['files']!=actual['files']):
        raise ValueError('stale or inconsistent delivery artifacts')


def write_summary(root='.'):
    root=Path(root)
    def read(path):return json.loads((root/path).read_text(encoding='utf-8'))
    validation=read('results/visualization/replay_validation_v1.json')
    figures=read('results/visualization/static_figures_v1.json')
    demo=read('results/visualization/demo_export_v1.json')
    actual=check_bundle(root/'results/demo')
    verify_delivery(validation,figures,demo,actual)
    if digest(root/'results/registry.csv')!=validation['registry_sha256']:raise ValueError('registry changed since replay validation')
    paired=RegistryFigures(root/'results/registry.csv').paired()
    require_exact(figures['paired_mean'],paired['mean'],'delivery paired mean')
    lines=['# Plan 004 visualization delivery','',
        'Generated by `uv run python scripts/report_visualization.py` from registered data and exported manifests. This reporting command performs no policy evaluation or test cache/output access. [Evaluation protocol](../../docs/PROTOCOL.md); [playback/live guide](../../docs/DEMO_GUIDE.md).','',
        '## Recorded-sequence replay','',
        '| Oracle | Episodes | Check |','|---|---:|---|',
        f'| A: four canonical baseline methods | {validation["counts"]["A"]} | Every original step field and every available summary matched exactly |',
        f'| B: six canonical learner arms | {validation["counts"]["B"]} | Every stored sequence and summary matched exactly |','',
        f'Mismatches: {len(validation["mismatches"])}. Replay source commit: `{validation["commit"]}`. No policy/planner calls. [Validation manifest](replay_validation_v1.json).',
        '',validation['equality'],'',validation['auc_definition'],'',
        'AUC matching is one scalar consistency check, not a mathematical final-coverage guarantee. Historical learner final coverage and joints were not separately stored. Label: **derived from replay; consistent with partial oracle**. Each demo episode carries stage/matched fields and the full-oracle manifest hash.','',
        'The twelve step fields are `pass`, `t_move`, `t_scan`, `t_home`, `joint_motion`, `total_joint_motion`, `cycle_time`, `coverage`, `coverage_nsc`, `coverage_raw`, `nominal_coverage`, `repair`. The learner summaries include time/normalized time, success/censoring, pass counts, repair count, joint motion, coverage/NSC/raw at 5 and 10, and AUC.','',
        '## Static figures','',
        f'{figures["figure_count"]} figure triples; each PNG has PDF and JSON source metadata beside it. Existing min–max plots remain. Source commit for these figures: `{figures["commit"]}`.','',
        '| Figure | PNG | PDF | Sources / transformations |','|---|---|---|---|']
    for name in figures['files']:
        if not name.endswith('.png'):continue
        stem=Path(name).stem
        side=read(f'results/figures/{stem}.json')
        if side['registry_sha256']!=validation['registry_sha256']:raise ValueError('figure registry snapshot mismatch')
        lines.append(f'| {stem} | [PNG](../figures/{stem}.png) | [PDF](../figures/{stem}.pdf) | [JSON](../figures/{stem}.json) |')
    lines+=['',f'Paired H-forward split mean (D-055): `{paired["mean"]:.15f}`, exactly the original binary64 verdict. No significance test.','',
        'Test views read only registry metrics: no test move/scan/home decomposition. VAL time components use every verified episode. Decision latency is VAL/seed-0/this-machine warm-call timing (D-066); the quality/latency view is explicitly cross-split and descriptive.','',
        'Learning curves use ten actual twenty-point VAL histories, no smoothing or aggregate-band reconstruction. Colors follow one shared method style dictionary; highlighted line styles encode best/lower-median/worst rank. The fifth sorted run is the lower median, ties go to smaller seed. The Tanaka adaptation uses ten rather than one hundred runs and official-policy final score rather than whole-run mean return. Alternative curve-mean rankings are stored as information only.','',
        '| Arm | Best seed | Lower-median seed | Worst seed | Official-score order | Alternative curve-mean order |',
        '|---|---:|---:|---:|---|---|']
    rankings=read('results/figures/p004_b_learning_runs.json')['rankings']
    for label,r in rankings.items():
        lines.append(f'| {label} | {r["best"]} | {r["median"]} | {r["worst"]} | {r["ordered"]} | {r["alternative_curve_mean_order"]} |')
    lines+=['','Gallery: nominal area-weighted samples, number of saved reachable passes measuring each sample. Cividis uses the actual positive count range, with faint gray table-facing triangles (`n_z <= -cos(10 degrees)`) and unseen crosses. Saved candidate directions are shown in 2D azimuth/elevation in the part frame; legacy candidate_sphere filenames are retained. No new IK or visibility calculation. Per-part author/source/license/changes appear in the gallery and sidecars.','',
        '## External viewer files','',
        'Upload **all** files below together for an external viewer. The repository also provides a SHA-256-verifying recorded player and VAL-only live Viser demo: [guide](../../docs/DEMO_GUIDE.md). [Bundle format](../demo/README.md).','',
        '| File | Bytes |','|---|---:|']
    for name,size in actual['files'].items():lines.append(f'| [{name}](../demo/{name}) | {size} |')
    lines+= [f'| **Total, including manifest** | **{actual["total_bytes"]}** |','',
        'Budget: 12,000,000 bytes. No silent precision loss: float64 little-endian arrays, uint32 mesh indices and packed uint8 visibility. Big bit order, pass-major rows, original sample correspondence. Invalid IK/collision passes are zero-filled with explicit validity masks and must never be animated.','',
        f'Manifest SHA-256: `{actual["manifest_sha256"]}`. The manifest hashes every other file; its own hash is in [the external export record](demo_export_v1.json). Git disables text conversion for this bundle so Windows checkout preserves the exact bytes.','',
        'Coordinates: **mesh nominal, points variant v0; deviation up to approximately 1.5 mm**. Meshes retain their original normalized nominal triangles; no simplification. Joints are derived with unchanged ENV v4 wrap/limit handling; home is a separate final row.','',
        '## Attribution and unresolved license versions','',
        '| Part | Name | Author | Recorded license | Version |','|---|---|---|---|---|']
    for fid in demo['parts']:
        credit=read(f'results/demo/part_{fid}_v0.json')['attribution']
        lines.append(f'| {fid} | [{credit["name"]}]({credit["source_url"]}) | {credit["author"]} | {credit["license"]} | {credit["version_status"]} |')
    lines+=['','No license version is inferred. Version-specific official deed URLs remain null; the CC overview is labeled as an overview. Display attribution, source, recorded family, missing-version status and modifications; BY-SA derivatives retain the same license. Resolve source versions before public redistribution.','',
        '## Reproduction','',
        'Run from the repository root after `uv sync`. Rendering requires the existing allowed train/VAL caches and the ignored, hashed VAL replay artifact. A source-only checkout can inspect the bundle and regenerate this summary without test access.','',
        '```powershell','uv run pytest -q','uv run python scripts/report_figures.py','uv run python scripts/export_demo.py','uv run python scripts/report_visualization.py','```','',
        'Render/export commands require committed source. The exporter refuses to replace an existing destination; its `export(directory=...)` API accepts a fresh directory under results/ for controlled reproduction. The original replay validator also preserves its exclusive output record; do not overwrite it or reopen the test campaign.','',
        'Development notes: a schema-construction syntax error was fixed before export. Windows private-temporary-directory ACL inheritance initially prevented Git from reading the bundle; enabling inheritance did not change any bytes/hash. The exporter now creates fresh destination files with inherited access rather than moving a private directory. The corresponding regression test and byte-preserving Git attributes pass.','']
    live_path=root/'results/visualization/live_validation_v1.json'
    if live_path.exists():
        live=json.loads(live_path.read_text(encoding='utf-8'))
        if live['registry_sha256']!=validation['registry_sha256'] or live['bundle_manifest_sha256']!=actual['manifest_sha256']:raise ValueError('live diagnostic input snapshot mismatch')
        lines+=['## Local VAL demo validation','',
            '[Headless diagnostic](live_validation_v1.json) from committed source `'+live['commit']+'`. Five live methods plus two saved CAD sequences; fixed cases only, no tuning or registry write.','',
            '| Method | Variant | Seed | Mode | Exact match |','|---|---|---:|---|---|']
        for c in live['cases']:lines.append(f'| {c["method"]} | {c["variant"]} | {c["seed"]} | {c["mode"]} | {c["verification"]["exact"]} |')
        lines+=['','MCTS uses the second variant to exercise restoration of the original shared RNG stream. The runtime always checks the chosen episode; these fixed headless cases are not an exhaustive UI/seed sweep.','',
            '[Actual local browser screenshot](live_demo_v1.png) and [capture provenance](live_demo_v1.json): SARSA/linear, VAL 271875_v0, seed 0, return-home completed and exact-match message visible. No automated browser-test suite.','',
            '```powershell','uv sync --extra demo','uv run --extra demo python scripts/live_demo.py --recorded --port 8080','uv run --extra demo python scripts/live_demo.py --port 8080','```','',
            'Live decision/scene-update latency is this-machine, display-load-inclusive (animation waits excluded), and not D-066-comparable. Static mode checks the immutable bundle first and needs no original cache/checkpoint; its schematic laser fan uses the fixed repository sensor config.','']
    path=root/'results/visualization/README.md';path.write_text('\n'.join(lines),encoding='utf-8')
    return path
